<?php require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../includes/functions.php';$pageTitle='Admin login';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){check_token();$s=$pdo->prepare("SELECT id,full_name,password_hash FROM users WHERE email=? AND role='admin' LIMIT 1");$s->execute([trim((string)($_POST['email']??''))]);$a=$s->fetch();if($a&&password_verify((string)($_POST['password']??''),$a['password_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=$a['id'];$_SESSION['admin_name']=$a['full_name'];header('Location: dashboard.php');exit;}$error='Invalid admin credentials.';}require __DIR__.'/../includes/header.php'; ?><div class="container section-space" style="max-width:460px"><div class="panel"><h1 class="h3 mb-4">Admin sign in</h1><?php if($error): ?><div class="alert alert-danger"><?=e($error)?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?=e(token())?>"><label class="form-label">Email</label><input class="form-control mb-3" name="email" type="email" required><label class="form-label">Password</label><input class="form-control mb-4" name="password" type="password" required><button class="btn btn-dark w-100">Sign in</button></form><p class="small text-secondary mt-3">No default admin is included. See README for setup.</p></div></div><?php require __DIR__.'/../includes/footer.php'; ?>